// MARK: - 内嵌插画素材
//
// 角色图取自动画片原画面，抠掉草地背景后以 base64 内嵌，避免依赖资源包
// （Widget Extension 加资源要在 Xcode 工程里配 build phase，容易漏打包）。
// 平涂卡通图压缩后每张只有 2~19KB，解码开销可以忽略。

@available(iOS 16.1, *)
enum SignInArt {
    static let full: UIImage? = decode(SignInArtBase64.full)
    static let shin: UIImage? = decode(SignInArtBase64.shin)
    static let dog: UIImage? = decode(SignInArtBase64.dog)

    private static func decode(_ s: String) -> UIImage? {
        guard let data = Data(base64Encoded: s, options: .ignoreUnknownCharacters) else {
            return nil
        }
        return UIImage(data: data)
    }
}

